excels.excel:

EXPORT WITH SHEET="季度销售目标达成对比表", HEADER=true,
    MAPPING={"a":"区域","b":"季度目标","c":"实际销售","d":"目标差额","e":"达成率","f":"评级"},
    FORMAT={"b":"#,##0.00","c":"#,##0.00","d":"#,##0.00","e":"0.00%"},
    FORMULAS={
        D2:'C2-B2',E2:'C2/B2', D3:'C3-B3',E3:'C3/B3',
        D4:'C4-B4',E4:'C4/B4', D5:'C5-B5',E5:'C5/B5',
        D6:'C6-B6',E6:'C6/B6',
        B7:'SUM(B2:B6)',C7:'SUM(C2:C6)',D7:'C7-B7',E7:'C7/B7'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        E4:{color:red,bold:true}
    }
